import { test } from 'node:test';
import assert from 'node:assert/strict';
import { compareFarm } from '../src/shared/compare.js';
import { FARM_FORMAT, parseFarm } from '../src/shared/farm.js';
import { emptyWorkspace, newProfile, newRule } from '../src/shared/model.js';
import { applyQuickStart } from '../src/shared/quickstarts.js';

// The AD FS side is written out by hand, as AD FS returns it (CRLF, other
// indentation), not generated by the code under test.
const WAN = 'http://schemas.microsoft.com/ws/2008/06/identity/claims/windowsaccountname';
const GROUP_SID = 'http://schemas.microsoft.com/ws/2008/06/identity/claims/groupsid';
const MAIL_RULE = [
  '@RuleName = "Send e-mail"',
  `c:[Type == "${WAN}", Issuer == "AD AUTHORITY"]`,
  '   => issue(store = "Active Directory", types = ("http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress"), query = ";mail;{0}", param = c.Value);',
].join('\r\n');
const PERMIT_SALES = [
  '@RuleName = "Permit members of an AD group"',
  `EXISTS([Type == "${GROUP_SID}", Value == "S-1-5-21-1-2-3-1105", Issuer == "AD AUTHORITY"])`,
  ' => issue(Type = "http://schemas.microsoft.com/authorization/claims/permit", Value = "true");',
].join('\r\n');

const rp = (Name, fields = {}) => ({
  Name, Enabled: true, AccessControlPolicyName: '', AccessControlPolicyParameters: '', IssuanceAuthorizationRules: '', IssuanceTransformRules: '', ...fields,
});
const farm = (relyingParties, extra = {}) => parseFarm(JSON.stringify({
  Format: FARM_FORMAT, RelyingPartyTrusts: relyingParties, ClaimsProviderTrusts: [{ Name: 'Active Directory', AcceptanceTransformRules: '' }],
  Groups: { 'S-1-5-21-1-2-3-1105': 'CONTOSO\\Sales' }, ...extra,
}));

// "Mail": a policy and the e-mail claim. "Sales": access rules for a group by name.
function workspace() {
  const ws = emptyWorkspace();
  const mail = newProfile('Mail', 'app');
  mail.accessPolicy = { name: 'Permit everyone', groups: [] };
  applyQuickStart(ws, mail, 'issuanceTransform', 'email');
  const sales = newProfile('Sales', 'app');
  sales.ruleSets.issuanceTransform.enabled = false;
  sales.ruleSets.issuanceAuthorization.enabled = true;
  applyQuickStart(ws, sales, 'issuanceAuthorization', 'permitGroup');
  sales.ruleSets.issuanceAuthorization.rules[0].conditions[0].value = 'CONTOSO\\Sales';
  ws.profiles.push(mail, sales);
  return { ws, mail, sales };
}
const states = (result) => result.rows.map((r) => [r.name, r.state]);
const detailsOf = (result, name) => result.rows.find((r) => r.name === name).details;

test('what AD FS has is the same, with SIDs, CRLF and indentation; built-in trusts are not listed', () => {
  const { ws } = workspace();
  const result = compareFarm(ws, farm([
    rp('mail ', { AccessControlPolicyName: 'Permit everyone', IssuanceTransformRules: MAIL_RULE }),
    rp('Sales', { IssuanceAuthorizationRules: PERMIT_SALES }),
    rp('Device Registration Service'),
    rp('Payroll'),
  ]));
  assert.deepEqual(states(result), [['Mail', 'same'], ['Sales', 'same']]);
  assert.deepEqual(result.onlyInAdfs, ['Payroll']);
  // A group by SID here matches the group by name there too.
  const { ws: bySid, sales } = workspace();
  sales.ruleSets.issuanceAuthorization.rules[0].conditions[0].value = 'S-1-5-21-1-2-3-1105';
  assert.equal(compareFarm(bySid, farm([rp('Sales', { IssuanceAuthorizationRules: PERMIT_SALES })])).rows[1].state, 'same');
});

test('labels only: rule names and the templates AD FS Management writes', () => {
  const { ws } = workspace();
  const templated = `@RuleTemplate = "LdapClaims"\r\n${MAIL_RULE.replace('Send e-mail', 'E-mail from AD')}`;
  const result = compareFarm(ws, farm([rp('Mail', { AccessControlPolicyName: 'Permit everyone', IssuanceTransformRules: templated })]));
  assert.deepEqual(detailsOf(result, 'Mail'), ['Claims to send: only the rule names differ, which the export sets']);
});

test('real differences: other rules on one line, the policy, its groups, leftover parameters', () => {
  const { ws, mail } = workspace();
  mail.ruleSets.issuanceTransform.rules = [newRule('raw', { text: '@RuleName = "A" => issue(Type = "x", Value = "1");' })];
  const oneLine = compareFarm(ws, farm([rp('Mail', { AccessControlPolicyName: 'Permit everyone', IssuanceTransformRules: '@RuleName = "B" => issue(Type = "x", Value = "2");' })]));
  assert.deepEqual(detailsOf(oneLine, 'Mail'), ['Claims to send: the rules differ']);

  const policies = (name, parameters) => compareFarm(workspace().ws, farm([rp('Mail', {
    AccessControlPolicyName: name, AccessControlPolicyParameters: parameters, IssuanceTransformRules: MAIL_RULE,
  })]));
  assert.deepEqual(detailsOf(policies('Permit specific group', ''), 'Mail'), ['Who gets access: AD FS has the policy "Permit specific group", here it is "Permit everyone"']);
  assert.deepEqual(detailsOf(policies('', ''), 'Mail'), ['Who gets access: AD FS uses rules instead of the access control policy "Permit everyone"']);
  // The export script clears parameters left from a policy that had groups.
  assert.deepEqual(detailsOf(policies('Permit everyone', '{"GroupParameter":["S-1-5-21-1-2-3-500"]}'), 'Mail'),
    ['Who gets access: AD FS has policy parameters, which the export clears']);

  const grouped = workspace();
  grouped.mail.accessPolicy = { name: 'Permit specific group', groups: ['CONTOSO\\Sales'] };
  const sameGroup = compareFarm(grouped.ws, farm([rp('Mail', {
    AccessControlPolicyName: 'Permit specific group', AccessControlPolicyParameters: '{"GroupParameter":["S-1-5-21-1-2-3-1105"]}', IssuanceTransformRules: MAIL_RULE,
  })]));
  assert.equal(sameGroup.rows[0].state, 'same');
  const otherGroup = compareFarm(grouped.ws, farm([rp('Mail', {
    AccessControlPolicyName: 'Permit specific group', AccessControlPolicyParameters: '{"GroupParameter":["S-1-5-21-1-2-3-999"]}', IssuanceTransformRules: MAIL_RULE,
  })]));
  assert.deepEqual(detailsOf(otherGroup, 'Mail'), ["Who gets access: the policy's groups differ"]);
});

test('a step with errors is not compared and never shows as the same', () => {
  const { ws, mail } = workspace();
  mail.ruleSets.issuanceTransform.rules.push(newRule('claim', { type: '' }));
  const result = compareFarm(ws, farm([rp('Mail', { AccessControlPolicyName: 'Permit everyone', IssuanceTransformRules: 'totally different' })]));
  assert.deepEqual(result.rows[0].state, 'skipped');
  assert.deepEqual(detailsOf(result, 'Mail'), ['Claims to send has errors here, so it was not compared']);
});

test('missing trusts: created by the export, or left out with the reason of that one', () => {
  const ws = emptyWorkspace();
  const created = newProfile('New one', 'app');
  created.accessPolicy = { name: 'Permit everyone', groups: [] };
  created.trust = { mode: 'metadata', metadataUrl: 'https://new.example.com/meta', identifier: '', protocol: 'saml', replyUrl: '' };
  const blocked = newProfile('Blocked', 'app');
  blocked.trust = { ...created.trust, metadataUrl: 'https://blocked.example.com/meta' };
  // Names that start the same must not borrow each other's reasons.
  const hr = newProfile('HR', 'app');
  const payroll = newProfile('HR: Payroll', 'app');
  payroll.ruleSets.issuanceTransform.rules.push(newRule('claim', { type: '' }));
  ws.profiles.push(created, blocked, hr, payroll);
  const result = compareFarm(ws, farm([rp('HR'), rp('HR: Payroll')]));
  assert.deepEqual(detailsOf(result, 'New one'), ['Not in AD FS yet. The export creates it']);
  assert.match(detailsOf(result, 'Blocked')[0], /^Not in AD FS, and the export leaves it out: The trust settings have 1 error/);
  assert.deepEqual(detailsOf(result, 'HR'), ['Nothing here to compare: the export leaves this trust as it is']);
  assert.match(detailsOf(result, 'HR: Payroll')[0], /^Claims to send has 1 error/);
  assert.deepEqual(compareFarm(emptyWorkspace(), farm([rp('X')])).rows, []);
});
